"""Return singular equivalent POS-tag for given POS-tag."""
def singularize(args: Any, premise: Any) -> object {
    pos = args[0];
    singularize_dict = {
        'NNS': 'NN',
        'NN': 'NN',
        'NNPS': 'NNP',
        'VBP': 'VBZ',
        'VBD': 'VBD',
        'VB': 'VB',
        'VBZ': 'VBZ',
        'VBN': 'VBN',
        'MD': 'MD'
    };
    try {
        sing_pos = singularize_dict[pos];
    } except KeyError {
        return pos;
    }
    return sing_pos;
}

